import { Box, defineTask } from '@caemble/core'

// Peak exp(+i*omega*t) pressure. Inlet outward normal is -X; the matched outlet is rho*c.
export default defineTask({
  kernel: { name: 'pressure-acoustics', version: '1.1.0' },
  lengthUnit: 'm',
  config: () => ({
    parameters: { spatialResolution: { dtype: 'float64', value: 0.02, quantityKind: 'Length', unit: 'm' } },
    initializations: [
      { methodId: 'acoustics.fluid', target: ['experiment.geometry.fluid'], parameters: {} },
      { methodId: 'acoustics.spectrum', target: [], parameters: {
        frequencies: { dtype: 'float64', quantityKind: 'Frequency', unit: 'Hz',
                       value: [100, 137.5, 175, 212.5, 250, 287.5, 325, 362.5, 400], axes: [{ length: 9 }] },
      } },
    ],
    boundaryConditions: [
      { methodId: 'acoustics.surface-motion', target: ['experiment.surface.inlet'], parameters: {} },
      { methodId: 'acoustics.impedance', target: ['experiment.surface.outlet'], parameters: {
        resistance: { dtype: 'float64', value: 1.2 * 343, quantityKind: 'acoustics.SpecificAcousticImpedance', unit: 'Pa.s.m-1' },
      } },
    ],
    outputs: [
      { methodId: 'acoustics.pressure', key: 'pressure', target: ['task.geometry.outputGrid'], parameters: { gridShape: [24, 4, 4] } },
      { methodId: 'acoustics.pressure', key: 'pressureProbe', target: ['task.geometry.probe'], parameters: { gridShape: [1, 1, 1] } },
    ],
    exports: [],
  }),
  geometry: ({ vars }) => <>
    <Box id="output-grid" size={[Number(vars.length), Number(vars.width), Number(vars.height)]} position={[Number(vars.length) / 2, 0, 0]} />
    <Box id="probe" size={[0.001, 0.001, 0.001]} position={[0.8 * Number(vars.length), 0, 0]} />
  </>,
  geometryGroup: { outputGrid: ['output-grid'], probe: ['probe'] },
})

files.tasks/structure.tsx:
import { Box, defineTask } from '@caemble/core'

// A 1 N peak load acts inward on the plate back. The air pressure is not fed back.
export default defineTask({
  kernel: { name: 'structural-mechanics', version: '6.1.0' },
  lengthUnit: 'm',
  config: ({ vars }) => ({
    parameters: {
      analysis: 'harmonic', geometricNonlinear: false, maxIterations: 40,
      relativeTolerance: { dtype: 'float64', value: 1e-8, quantityKind: 'Dimensionless', unit: '1' },
      spatialResolution: { dtype: 'float64', value: Number(vars.thickness) / 2, quantityKind: 'Length', unit: 'm' },
    },
    initializations: [
      { methodId: 'fea.body', target: ['experiment.geometry.plate'], parameters: {} },
      { methodId: 'fea.spectrum', target: [], parameters: { modeCount: 1,
        frequencies: { dtype: 'float64', quantityKind: 'Frequency', unit: 'Hz',
                       value: [100, 137.5, 175, 212.5, 250, 287.5, 325, 362.5, 400], axes: [{ length: 9 }] },
      } },
    ],
    boundaryConditions: [
      { methodId: 'fea.fixed', target: ['experiment.surface.plateRim'], parameters: {
        components: { dtype: 'string', value: ['x', 'y', 'z'], axes: [{ length: 3 }] },
      } },
      { methodId: 'fea.pressure', target: ['experiment.surface.plateBack'], parameters: {
        pressure: { dtype: 'float64', value: 1 / (Number(vars.width) * Number(vars.height)), quantityKind: 'Pressure', unit: 'Pa' },
      } },
    ],
    outputs: [{ methodId: 'fea.harmonic-displacement', key: 'displacement', target: ['task.geometry.outputGrid'], parameters: { gridShape: [2, 12, 12] } }],
    exports: [{ methodId: 'fea.harmonic-surface-motion', key: 'surfaceMotion', target: ['experiment.surface.plateFront'], parameters: {} }],
  }),
  geometry: ({ vars }) => <Box id="output-grid" size={[Number(vars.thickness), Number(vars.width), Number(vars.height)]} position={[-Number(vars.thickness) / 2, 0, 0]} />,
  geometryGroup: { outputGrid: ['output-grid'] },
})
